def transform(grid):
    """Extend each hollow 3x3 marker away from its rail, marking the trail red."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find centers of 3x3 green rings with a blue center.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))
    if not centers:
        return g

    # The long blue rails determine the direction of propagation.
    row_rails = [r for r in range(h) if sum(x == 2 for x in g[r]) >= max(4, int(w * .7))]
    col_rails = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= max(4, int(h * .7))]
    travel_horizontal = bool(col_rails) and (not row_rails or len(col_rails) >= len(row_rails))
    rails = col_rails if travel_horizontal else row_rails

    for r, c in centers:
        pos = c if travel_horizontal else r
        limit = w if travel_horizontal else h
        # The ring itself occupies one cell on either side along the travel axis;
        # continue outward beyond it in both available directions.
        for direction in (-1, 1):
            i = pos + 2 * direction
            while 0 <= i < limit:
                rr, cc = (r, i) if travel_horizontal else (i, c)
                if g[rr][cc] == 0:
                    g[rr][cc] = 1
                i += direction
        # At each other blue rail crossed by this trail, reproduce the marker ring
        # in red around the preserved blue center.
        for rail in rails:
            if rail == pos:
                continue
            rr, cc = (r, rail) if travel_horizontal else (rail, c)
            if g[rr][cc] != 2:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    nr, nc = rr + dr, cc + dc
                    if (dr, dc) != (0, 0) and 0 <= nr < h and 0 <= nc < w and g[nr][nc] == 0:
                        g[nr][nc] = 1
    return g
