def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))
    row_rails = [r for r in range(h) if sum(v == 2 for v in g[r]) >= max(4, int(w * .7))]
    col_rails = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= max(4, int(h * .7))]
    horizontal_rays = bool(col_rails) and (not row_rails or len(col_rails) >= len(row_rails))

    for r, c in centers:
        if horizontal_rays:
            # Side-to-side ray through the marker.
            for cc in range(w):
                if g[r][cc] == 0:
                    g[r][cc] = 1
                if cc in col_rails and cc != c and g[r][cc] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, cc + dc
                            if (dr, dc) != (0, 0) and 0 <= nr < h and 0 <= nc < w and g[nr][nc] in (0, 2):
                                g[nr][nc] = 1
        else:
            # When parallel horizontal rails exist, extend away from the nearest
            # other rail; with no other rail, the marker projects both ways.
            others = [rr for rr in row_rails if rr != r]
            if others:
                target = min(others, key=lambda rr: abs(rr - r))
                direction = 1 if target > r else -1
                positions = range(r + direction, h if direction > 0 else -1, direction)
            else:
                positions = range(h)
            for rr in positions:
                if g[rr][c] == 0:
                    g[rr][c] = 1
                if rr in row_rails and rr != r and g[rr][c] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, c + dc
                            if (dr, dc) != (0, 0) and 0 <= nr < h and 0 <= nc < w and g[nr][nc] in (0, 2):
                                g[nr][nc] = 1
    return g

def transform(grid):
    """Project each 3x3 green marker along its blue rail's perpendicular axis."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(
                g[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if (dr, dc) != (0, 0)
            ):
                centers.append((r, c))
    row_rails = [r for r in range(h) if sum(x == 2 for x in g[r]) >= max(4, int(w * .7))]
    col_rails = [c for c in range(w) if sum(g[r][c] == 2 for r in range(h)) >= max(4, int(h * .7))]
    horizontal = bool(col_rails) and (not row_rails or len(col_rails) >= len(row_rails))
    for r, c in centers:
        if horizontal:
            # Ray fills the row; each crossed parallel rail gets a red 3x3 halo.
            for cc in range(w):
                if g[r][cc] == 0:
                    g[r][cc] = 1
                if cc in col_rails and cc != c and g[r][cc] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = r + dr, cc + dc
                            if (dr, dc) != (0, 0) and 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 3:
                                g[nr][nc] = 1
        else:
            # Vertical counterpart; project both directions from the marker.
            for rr in range(h):
                if g[rr][c] == 0:
                    g[rr][c] = 1
                if rr in row_rails and rr != r and g[rr][c] == 2:
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            nr, nc = rr + dr, c + dc
                            if (dr, dc) != (0, 0) and 0 <= nr < h and 0 <= nc < w and g[nr][nc] != 3:
                                g[nr][nc] = 1
    return g
